@torch.jit.script
def _candidate_normalized_scan(input_gates: torch.Tensor, hidden: torch.Tensor,
                               weight_hh: torch.Tensor, bias_hh: torch.Tensor,
                               norm_weight: torch.Tensor,
                               norm_bias: torch.Tensor) -> torch.Tensor:
    input_reset, input_update, input_candidate = input_gates.chunk(3, dim=-1)
    outputs = torch.jit.annotate(list[torch.Tensor], [])
    for t in range(input_gates.size(1)):
        recurrent = torch.nn.functional.linear(hidden, weight_hh, bias_hh)
        hidden_reset, hidden_update, hidden_candidate = recurrent.chunk(3, dim=-1)
        reset = torch.sigmoid(input_reset[:, t] + hidden_reset)
        update = torch.sigmoid(input_update[:, t] + hidden_update)
        candidate_preactivation = input_candidate[:, t] + reset * hidden_candidate
        candidate = torch.tanh(torch.nn.functional.layer_norm(
            candidate_preactivation, [hidden.size(1)], norm_weight, norm_bias, 1e-5
        ))
        hidden = candidate + update * (hidden - candidate)
        outputs.append(hidden)
    return torch.stack(outputs, dim=1)


class CandidateNormalizedGRU(nn.GRU):
    def __init__(self, input_size: int, hidden_size: int, num_layers: int = 1,
                 batch_first: bool = True, dropout: float = 0.0):
        super().__init__(input_size, hidden_size, num_layers=num_layers,
                         batch_first=batch_first, dropout=dropout)
        self.candidate_norms = nn.ModuleList([
            nn.LayerNorm(hidden_size) for _ in range(num_layers)
        ])

    def forward(self, input: torch.Tensor, hx: torch.Tensor | None = None):
        output = input if self.batch_first else input.transpose(0, 1)
        if hx is None:
            hx = output.new_zeros(self.num_layers, output.size(0), self.hidden_size)
        final_hidden = []
        for layer, norm in enumerate(self.candidate_norms):
            input_gates = torch.nn.functional.linear(
                output, getattr(self, f"weight_ih_l{layer}"),
                getattr(self, f"bias_ih_l{layer}")
            )
            output = _candidate_normalized_scan(
                input_gates, hx[layer], getattr(self, f"weight_hh_l{layer}"),
                getattr(self, f"bias_hh_l{layer}"), norm.weight, norm.bias
            )
            final_hidden.append(output[:, -1])
            if layer + 1 < self.num_layers and self.dropout > 0.0:
                output = torch.nn.functional.dropout(
                    output, p=self.dropout, training=self.training
                )
        if not self.batch_first:
            output = output.transpose(0, 1)
        return output, torch.stack(final_hidden, dim=0)


